#include <IQM/hdrvdp3/srgb_quality96_runtime_double.h>
#include <vulkan_instance.h>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <bit>
#include <algorithm>
#include <limits>
using namespace IQM::HDRVDP3;namespace fs=std::filesystem;
std::vector<double> read(const fs::path&p,size_t n){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f||f.tellg()!=std::streamoff(n*8))throw std::runtime_error("Reference shape "+p.string());std::vector<double> v(n);f.seekg(0);f.read(reinterpret_cast<char*>(v.data()),n*8);return v;}
int main(int argc,char**argv){try{if(argc!=4)throw std::invalid_argument("Usage: v2-runtime cpu-root fresh-output");fs::path runtime=argv[1],cpu=argv[2],out=argv[3];if(fs::exists(out)||!fs::create_directories(out))throw std::invalid_argument("Fresh output");auto model=load_srgb_quality96_runtime_double(runtime,"oled");IQM::Bin::VulkanInstance instance(true,"NVIDIA",true);SRGBQuality96GPUDouble gpu(*instance.physicalDevice(),*instance.device(),*instance.queue(),instance.queueFamilyIndex,true,model.shaders,model.projection);size_t words=0;
 auto compare=[&](const std::vector<double>&a,const std::vector<double>&b,const std::string& field){if(a.size()!=b.size())throw std::runtime_error("Shape");for(size_t i=0;i<a.size();++i)if(std::bit_cast<uint64_t>(a[i])!=std::bit_cast<uint64_t>(b[i]))throw std::runtime_error(field+" mismatch at "+std::to_string(i));words+=a.size();};
 for(std::string native:{"native","native_ramps","native_identity_v2"})for(std::string display:{"led-lcd-srgb","led-lcd-wcg","oled"}){auto spectral=load_srgb_quality96_runtime_double(runtime,display).spectral;for(unsigned side=1;side<=2;++side){const auto name=display+"_"+std::to_string(side),prefix=(cpu/native/name).string();auto optical=read(prefix+"_optical.f64",27648);auto result=gpu.project(optical,spectral);for(auto item:{std::pair{"response",&result.response},std::pair{"clamped",&result.clamped},std::pair{"adaptation_input",&result.adaptation_input}}){compare(*item.second,read(prefix+"_"+item.first+".f64",item.second->size()),item.first);std::ofstream f(out/(native+"_"+name+"_"+item.first+".f64"),std::ios::binary);f.write(reinterpret_cast<const char*>(item.second->data()),item.second->size()*8);}compare(result.adaptation_log,read(prefix+"_conv4_input.f64",9216),"adaptation_log");}}
 const auto nativeWords=words;for(std::string display:{"led-lcd-srgb","led-lcd-wcg","oled"}){auto spectral=load_srgb_quality96_runtime_double(runtime,display).spectral;std::vector<double> optical(27648);for(size_t i=0;i<optical.size();++i)optical[i]=i%13==0?-1e-4:i%13==1?0.:i%13==2?1e11:i%13==3?1e-5:.001+double(i%97)*.13;auto result=gpu.project(optical,spectral);for(double& v:optical)v=std::clamp(v,1e-5,1e10);auto expected=project_optical_rgb_double(optical,spectral,24);compare(result.response,expected.response,"control response");compare(result.clamped,expected.clamped,"control clamp");compare(result.adaptation_input,expected.adaptation_input,"control adaptation");compare(result.adaptation_log,expected.adaptation_log,"control log");}
 unsigned negatives=0;auto reject=[&](auto action){try{action();}catch(const std::exception&){++negatives;return;}throw std::runtime_error("Invalid projection input accepted");};reject([&]{gpu.project({},model.spectral);});std::vector<double> bad(27648,1.);bad[0]=std::numeric_limits<double>::quiet_NaN();reject([&]{gpu.project(bad,model.spectral);});bad[0]=std::numeric_limits<double>::infinity();reject([&]{gpu.project(bad,model.spectral);});
 std::ofstream(out/"PASS.txt")<<nativeWords<<" native Double words exact;"<<words-nativeWords<<" clamp control words exact;"<<negatives<<" rejection checks\n";std::cout<<words<<" words bitwise exact\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
